import SwiftUI

// WARN: Generated by Big Pickle (Opencode): Be cautious
struct CreateDefaultFlask: View {
    @Environment(FlaskLibrary.self) private var flaskLibrary
    @Binding var isPresented: Bool

    @State private var wineLibrary = WineLibrary()
    @State private var downloader = Downloader(.gptk3)
    @State private var error: FlaskError?

    var body: some View {
        VStack(spacing: 12) {
            Text("Setting up the default flask")

            switch downloader.state {
            case .downloading:
                ProgressView(value: downloader.progress)
                Text("Downloading GPTK 3.0...")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            case .extracting:
                ProgressView().progressViewStyle(.linear)
                Text("Installing GPTK 3.0...")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            case .complete:
                ProgressView()
                Text("Creating Flask...")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            case .idle:
                ProgressView()
            }
        }
        .padding()
        .task {
            await begin()
        }
        .onChange(of: downloader.state) { _, newState in
            switch newState {
            case .complete:
                Task { await finishSetup() }
            case .idle:
                if let downloaderError = downloader.error {
                    error = downloaderError
                }
            default:
                break
            }
        }
        .alert(item: $error) { error in
            Alert(
                title: Text(error.localizedDescription),
                message: Text(error.recoverySuggestion ?? ""))
        }
        .onDisappear {
            downloader.cancelDownload()
        }
    }

    @MainActor
    private func begin() async {
        do {
            try await wineLibrary.scan()

            if let runner = wineLibrary.runners.first {
                try await createFlask(with: runner)
            } else {
                downloader.startDownload()
            }
        } catch let flaskError as FlaskError {
            error = flaskError
        } catch {
            self.error = .unknownError
        }
    }

    @MainActor
    private func finishSetup() async {
        do {
            try await wineLibrary.scan()

            guard let runner = wineLibrary.runners.first else {
                throw FlaskError.wineError(detail: "Downloaded runner not found")
            }

            try await createFlask(with: runner)
        } catch let flaskError as FlaskError {
            error = flaskError
        } catch {
            self.error = .unknownError
        }
    }

    @MainActor
    private func createFlask(with runner: Runner) async throws {
        let flask = try await flaskLibrary.createFlask(
            runner, name: "Default", windowsString: "win10")

        flaskLibrary.flaskList.append(flask)
        isPresented = false
    }
}
